#!/usr/bin/env python3
# vUSAlink.py - SINGLE-FILE BUILD generated by bundle.py.
# Do not edit by hand; edit index.html / server.py and re-run: python bundle.py
"""
vUSAlink local server: serves the page, relays CPDLC to Hoppie, and serves live
VATSIM traffic + nearby-facility data for handoffs. Standard library only.

Run:   python server.py    then open http://localhost:8732/
"""

import json
import math
import os
import re
import sys
import time
import threading
import urllib.parse
import urllib.error
import urllib.request
import socket
import webbrowser
import base64
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

HOPPIE_URL = "https://www.hoppie.nl/acars/system/connect.html"
VATSIM_DATA_URL = "https://data.vatsim.net/v3/vatsim-data.json"
BOUNDARIES_URL = "https://raw.githubusercontent.com/vatsimnetwork/vatspy-data-project/master/Boundaries.geojson"
VATSPY_URL = "https://raw.githubusercontent.com/vatsimnetwork/vatspy-data-project/master/VATSpy.dat"
PORT = 8732
HERE = Path(__file__).resolve().parent
UA = {"User-Agent": "vUSAlink/1.0 (local CPDLC tool)"}
INDEX_HTML = base64.b64decode(
    ""
).decode("utf-8")

GROUND_GS = 50        # kts; at/below this we treat the aircraft as on the ground
LOW_ARR_FT = 2000     # arrivals below this altitude are dropped (landing)
HANDOFF_RANGE_NM = 200
BUFFER_NM = 20        # show aircraft this far OUTSIDE a center's border (lead time)
METAR_URL = "https://aviationweather.gov/api/data/metar"
_altimeter_cache = {}
_altimeter_lock = threading.Lock()


def fetch_url(url, timeout=20):
    req = urllib.request.Request(url, headers=UA)
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return r.read().decode("utf-8", "replace")


def normalize_icao(icao):
    icao = (icao or "").strip().upper()
    if len(icao) == 3 and icao.isalpha():
        if icao[0] == "Y":
            return "C" + icao
        return "K" + icao
    return icao


def parse_metar_altimeter(ob):
    raw = ob.get("rawOb") or ""
    m = re.search(r"\bA(\d{4})\b", raw)
    if m:
        return "%.2f" % (int(m.group(1)) / 100.0)
    m = re.search(r"\bQ(\d{4})\b", raw)
    if m:
        return "%.2f" % (int(m.group(1)) * 0.02953)
    altim = ob.get("altim")
    if altim is not None:
        try:
            return "%.2f" % (float(altim) * 0.02953)
        except (TypeError, ValueError):
            pass
    return None


def fetch_altimeter(icao):
    icao = normalize_icao(icao)
    if not re.match(r"^[A-Z]{4}$", icao):
        return None, "invalid airport id"
    now = time.time()
    with _altimeter_lock:
        hit = _altimeter_cache.get(icao)
        if hit and now - hit[0] < 300:
            return hit[1], None
    try:
        q = urllib.parse.urlencode({"ids": icao, "format": "json"})
        data = json.loads(fetch_url(METAR_URL + "?" + q, timeout=12))
    except Exception as e:
        return None, "metar fetch failed: %s" % e
    if not data:
        return None, "no metar for %s" % icao
    alt = parse_metar_altimeter(data[0])
    if not alt:
        return None, "no altimeter in metar"
    with _altimeter_lock:
        _altimeter_cache[icao] = (now, alt)
    return alt, None


# ---------------- Hoppie ----------------
def _braces(s):
    groups, depth, start = [], 0, None
    for i, ch in enumerate(s):
        if ch == "{":
            if depth == 0:
                start = i + 1
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0 and start is not None:
                groups.append(s[start:i]); start = None
    return groups


def parse_hoppie(text):
    text = (text or "").strip()
    res = {"ok": False, "error": None, "messages": [], "raw": text}
    if text.startswith("error"):
        inner = _braces(text); res["error"] = inner[0] if inner else text; return res
    if not text.startswith("ok"):
        res["error"] = text or "empty reply"; return res
    res["ok"] = True
    for grp in _braces(text):
        m = re.match(r"\s*(\S+)\s+(\S+)\s+(.*)", grp, re.DOTALL)
        if not m:
            continue
        inner = _braces(m.group(3).strip())
        res["messages"].append({"from": m.group(1), "type": m.group(2),
                                "packet": inner[0] if inner else m.group(3).strip()})
    return res


def hoppie_request(fields):
    data = urllib.parse.urlencode(fields).encode("utf-8")
    req = urllib.request.Request(HOPPIE_URL, data=data,
        headers={**UA, "Content-Type": "application/x-www-form-urlencoded"}, method="POST")
    with urllib.request.urlopen(req, timeout=15) as r:
        return r.read().decode("utf-8", "replace")


def hub_post(hub_url, path, body):
    """Forward a request to the central hub (used in hub mode)."""
    data = json.dumps(body).encode("utf-8")
    req = urllib.request.Request(hub_url.rstrip("/") + path, data=data,
        headers={**UA, "Content-Type": "application/json"}, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=20) as r:
            return json.loads(r.read().decode("utf-8", "replace"))
    except urllib.error.HTTPError as e:        # surface the hub's own error message
        try:
            return json.loads(e.read().decode("utf-8", "replace"))
        except Exception:
            return {"ok": False, "error": "hub error %s" % e.code}


# ---------------- VATSIM caches ----------------
_lock = threading.Lock()
_cache = {"feed": None, "feed_ts": 0, "bnd": None, "bnd_ts": 0,
          "apt": None, "fir": None, "vatspy_ts": 0}
FEED_TTL = 15
STATIC_TTL = 86400


def get_feed():
    now = time.time()
    if _cache["feed"] and now - _cache["feed_ts"] < FEED_TTL:
        return _cache["feed"]
    feed = json.loads(fetch_url(VATSIM_DATA_URL))
    _cache["feed"], _cache["feed_ts"] = feed, now
    return feed


def _polys_of(geom):
    t = geom.get("type"); c = geom.get("coordinates")
    if t == "Polygon":
        return [c]
    if t == "MultiPolygon":
        return c
    return []


def get_boundaries():
    now = time.time()
    if _cache["bnd"] and now - _cache["bnd_ts"] < STATIC_TTL:
        return _cache["bnd"]
    gj = json.loads(fetch_url(BOUNDARIES_URL))
    out = {}
    for f in gj.get("features", []):
        bid = (f.get("properties", {}).get("id") or "").upper()
        polys = _polys_of(f.get("geometry", {}))
        if not bid or not polys:
            continue
        minx = miny = float("inf"); maxx = maxy = float("-inf")
        for poly in polys:
            for ring in poly:
                for x, y in ring:
                    minx, maxx = min(minx, x), max(maxx, x)
                    miny, maxy = min(miny, y), max(maxy, y)
        if bid in out:
            out[bid]["polys"].extend(polys)
            ox0, oy0, ox1, oy1 = out[bid]["bbox"]
            out[bid]["bbox"] = (min(ox0, minx), min(oy0, miny), max(ox1, maxx), max(oy1, maxy))
        else:
            out[bid] = {"polys": polys, "bbox": (minx, miny, maxx, maxy)}
    _cache["bnd"], _cache["bnd_ts"] = out, now
    return out


def get_vatspy():
    """Return (airports, firs). Airports: {icao:{lat,lon,fir}}.
       Firs: [{icao,name,prefix,boundary}]."""
    now = time.time()
    if _cache["apt"] and now - _cache["vatspy_ts"] < STATIC_TTL:
        return _cache["apt"], _cache["fir"]
    text = fetch_url(VATSPY_URL)
    airports, firs, section = {}, [], None
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith(";"):
            continue
        if line.startswith("["):
            section = line.strip("[]").upper(); continue
        p = line.split("|")
        if section == "AIRPORTS" and len(p) >= 6:
            if len(p) >= 7 and p[6].strip() == "1":
                continue
            try:
                airports[p[0].strip().upper()] = {
                    "lat": float(p[2]), "lon": float(p[3]), "fir": p[5].strip().upper()}
            except ValueError:
                pass
        elif section == "FIRS" and len(p) >= 4:
            firs.append({"icao": p[0].strip().upper(), "name": p[1].strip(),
                         "prefix": p[2].strip().upper(),
                         "boundary": (p[3].strip().upper() or p[0].strip().upper())})
    _cache["apt"], _cache["fir"], _cache["vatspy_ts"] = airports, firs, now
    return airports, firs


# ---------------- geometry ----------------
def _pip_ring(x, y, ring):
    inside = False; n = len(ring); j = n - 1
    for i in range(n):
        xi, yi = ring[i][0], ring[i][1]
        xj, yj = ring[j][0], ring[j][1]
        if ((yi > y) != (yj > y)) and (x < (xj - xi) * (y - yi) / (yj - yi) + xi):
            inside = not inside
        j = i
    return inside


def point_in_entry(entry, lon, lat):
    minx, miny, maxx, maxy = entry["bbox"]
    if lon < minx or lon > maxx or lat < miny or lat > maxy:
        return False
    for poly in entry["polys"]:
        if poly and _pip_ring(lon, lat, poly[0]) and not any(_pip_ring(lon, lat, h) for h in poly[1:]):
            return True
    return False


def _pt_seg_nm(plon, plat, a, b, coslat):
    # local equirectangular projection (nm): x = lon*cos(lat)*60, y = lat*60
    ax, ay = a; bx, by = b
    px = (plon - ax) * coslat * 60.0; py = (plat - ay) * 60.0
    qx = (bx - ax) * coslat * 60.0;  qy = (by - ay) * 60.0
    seg2 = qx * qx + qy * qy
    t = 0.0 if seg2 == 0 else max(0.0, min(1.0, (px * qx + py * qy) / seg2))
    dx = px - t * qx; dy = py - t * qy
    return math.hypot(dx, dy)


def point_near_entry(entry, lon, lat, buffer_nm):
    """True if the point is inside the airspace OR within buffer_nm of its edge."""
    if point_in_entry(entry, lon, lat):
        return True
    minx, miny, maxx, maxy = entry["bbox"]
    m = buffer_nm / 60.0 + 0.2
    if lon < minx - m or lon > maxx + m or lat < miny - m or lat > maxy + m:
        return False
    coslat = math.cos(math.radians(lat))
    for poly in entry["polys"]:
        if not poly:
            continue
        ring = poly[0]
        for i in range(len(ring) - 1):
            if _pt_seg_nm(lon, lat, ring[i], ring[i + 1], coslat) <= buffer_nm:
                return True
    return False


def haversine_nm(lat1, lon1, lat2, lon2):
    R = 3440.065
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dphi = math.radians(lat2 - lat1); dl = math.radians(lon2 - lon1)
    a = math.sin(dphi / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin(dl / 2) ** 2
    return 2 * R * math.asin(min(1, math.sqrt(a)))


def _sample(entry, maxpts=120):
    pts = []
    for poly in entry["polys"]:
        if not poly:
            continue
        ring = poly[0]; step = max(1, len(ring) // maxpts)
        pts.extend(ring[i] for i in range(0, len(ring), step))
    return pts


def min_distance_nm(e1, e2):
    P, Q = _sample(e1), _sample(e2)
    best = 1e9
    for x1, y1 in P:
        for x2, y2 in Q:
            d = haversine_nm(y1, x1, y2, x2)
            if d < best:
                best = d
                if best == 0:
                    return 0.0
    return best


# ---------------- classification ----------------
def resolve_airspace(station, boundaries):
    s = (station or "").upper()
    if s in boundaries:
        return s
    for cand in (s.split("_")[0], s.split("-")[0]):
        if cand in boundaries:
            return cand
    return None


def airport_inside(apts, icao, airspace, entry):
    if not icao:
        return False
    a = apts.get(icao.upper())
    if not a:
        return False
    return a["fir"] == airspace or point_in_entry(entry, a["lon"], a["lat"])


def fmt_type(fp):
    ac = fp.get("aircraft_faa") or fp.get("aircraft_short") or ""
    m = re.match(r"^[A-Z]/(.+)$", ac)
    return m.group(1) if m else ac


# ---- navdata (optional): airways, fix coords, SID/STAR expansion ---------------
# See NAVDATA.md in vusalink-hub for schema and rebuild instructions.
from route_engine import configure_navdata, expand_route as _expand_route

_navdata = {"fixes": {}, "airways": {}, "procedures": {}, "loaded": False}


def _parse_fixes(raw_fixes):
    fixes = {}
    for k, v in (raw_fixes or {}).items():
        cands = []
        if v and isinstance(v[0], (int, float)):
            cands = [(float(v[0]), float(v[1]))]
        else:
            for pt in v or []:
                if pt and len(pt) >= 2:
                    cands.append((float(pt[0]), float(pt[1])))
        if cands:
            fixes[str(k).upper()] = cands
    return fixes


def _merge_procedures(target, src):
    for k, v in (src or {}).items():
        target[str(k).upper()] = v


def _procedure_paths(base_dir):
    paths = []
    env_proc = os.environ.get("VEDST_PROCEDURES", "").strip()
    if env_proc:
        paths.append(env_proc)
    for name in ("procedures.json", "procedures-ca.json"):
        p = os.path.join(base_dir, name)
        if os.path.isfile(p):
            paths.append(p)
    licensed = os.environ.get("VEDST_NAVCANADA_PROCEDURES", "").strip()
    if licensed:
        paths.append(licensed)
    return paths


def load_navdata():
    if _navdata["loaded"]:
        return _navdata
    _navdata["loaded"] = True
    path = os.environ.get("VEDST_NAVDATA", "navdata.json")
    base_dir = os.path.dirname(os.path.abspath(path)) or "."
    try:
        with open(path) as f:
            d = json.load(f)
        fixes = _parse_fixes(d.get("fixes", {}))
        airways = {str(k).upper(): [str(x).upper() for x in v]
                   for k, v in d.get("airways", {}).items()}
        procedures = {str(k).upper(): v for k, v in d.get("procedures", {}).items()}
        for proc_path in _procedure_paths(base_dir):
            try:
                with open(proc_path) as pf:
                    pd = json.load(pf)
                if isinstance(pd, dict) and pd and next(iter(pd.values()), None):
                    sample = next(iter(pd.values()))
                    if isinstance(sample, dict) and sample.get("type"):
                        _merge_procedures(procedures, pd)
                    else:
                        _merge_procedures(procedures, pd.get("procedures", pd))
            except Exception as e:
                sys.stderr.write("navdata: skip procedures %s: %s\n" % (proc_path, e))
        _navdata["fixes"] = fixes
        _navdata["airways"] = airways
        _navdata["procedures"] = procedures
        configure_navdata(fixes, airways, procedures)
        sys.stderr.write("navdata loaded: %d fixes, %d airways, %d procedures\n"
                         % (len(fixes), len(airways), len(procedures)))
    except Exception:
        pass  # no navdata -> graceful fallback to filed fixes only
    return _navdata


def expand_route(route, dep="", arr=""):
    """Ordered [{name, lat?, lon?, kind?}] for a filed route with airway + SID/STAR expansion."""
    load_navdata()
    nd = {
        "fixes": _navdata["fixes"],
        "airways": _navdata["airways"],
        "procedures": _navdata["procedures"],
        "airports": _navdata.get("airports") or {},
    }
    if not nd["airports"]:
        try:
            apts, _ = get_vatspy()
            nd["airports"] = {k: (v["lat"], v["lon"]) for k, v in apts.items()}
        except Exception:
            nd["airports"] = {}
    return _expand_route(route, dep=dep, arr=arr, navdata=nd)


def match_fir(callsign, firs):
    best = None
    for f in firs:
        pfx = f["prefix"]
        if pfx and callsign.startswith(pfx):
            if best is None or len(pfx) > len(best["prefix"]):
                best = f
    return best


def nearby_facilities(feed, airspace, entry, boundaries, apts, firs):
    facs, seen = [], set()
    fir_by_boundary = {f["boundary"]: f for f in firs}
    for c in feed.get("controllers", []):
        cs = (c.get("callsign") or "").upper()
        if not cs or cs in seen:
            continue
        freq = (c.get("frequency") or "").strip()
        if freq in ("199.998", "199.999", ""):    # observers / placeholder freqs
            continue
        suf = cs.split("_")[-1]
        if suf in ("CTR", "FSS"):
            f = match_fir(cs, firs)
            if not f:
                continue
            b = f["boundary"]
            if b == airspace or b not in boundaries:
                continue
            d = min_distance_nm(entry, boundaries[b])
            if d <= HANDOFF_RANGE_NM:
                nm = (f["name"].upper() + " CENTER") if suf == "CTR" else f["name"].upper()
                facs.append({"callsign": cs, "freq": freq, "name": nm,
                             "kind": "CTR", "dist": round(d), "icao": b})
                seen.add(cs)
        elif suf in ("APP", "DEP", "TWR"):
            base = cs.split("_")[0]
            cand = base if len(base) == 4 else ("K" + base if len(base) == 3 else None)
            a = apts.get(cand) if cand else None
            if a and (a["fir"] == airspace or point_in_entry(entry, a["lon"], a["lat"])):
                facs.append({"callsign": cs, "freq": freq, "name": cs,
                             "kind": suf, "dist": 0, "icao": ""})
                seen.add(cs)
    facs.sort(key=lambda x: (x["kind"] != "CTR", x["dist"], x["callsign"]))
    return facs


def classify_traffic(station):
    boundaries = get_boundaries()
    airspace = resolve_airspace(station, boundaries)
    if not airspace:
        return {"ok": False, "error": "no VATSIM boundary found for '%s' -- enter the "
                "ARTCC/FIR ICAO, e.g. KZJX" % station}
    entry = boundaries[airspace]
    apts, firs = get_vatspy()
    feed = get_feed()

    flights = []
    counts = {"DEP": 0, "ARR": 0, "OVR": 0, "INT": 0}
    for p in feed.get("pilots", []):
        fp = p.get("flight_plan") or {}
        dep = (fp.get("departure") or "").upper()
        arr = (fp.get("arrival") or "").upper()
        lat, lon = p.get("latitude"), p.get("longitude")
        gs = p.get("groundspeed") or 0
        alt_ft = p.get("altitude") or 0

        pos_in = lat is not None and lon is not None and point_near_entry(entry, lon, lat, BUFFER_NM)
        dep_in = airport_inside(apts, dep, airspace, entry)
        arr_in = airport_inside(apts, arr, airspace, entry)
        if not (pos_in or dep_in or arr_in):
            continue
        cat = ("INT" if dep_in and arr_in else "DEP" if dep_in else
               "ARR" if arr_in else "OVR")

        if gs < GROUND_GS:                       # on the ground / taxiing
            continue
        if cat == "ARR" and alt_ft < LOW_ARR_FT:  # landing
            continue

        counts[cat] += 1
        flights.append({
            "callsign": p.get("callsign", ""), "type": fmt_type(fp),
            "cid": p.get("cid", ""), "squawk": p.get("transponder", ""),
            "dep": dep, "arr": arr, "altFt": alt_ft,
            "fl": round(alt_ft / 100) if alt_ft else 0,
            "cruise": fp.get("altitude", ""), "route": fp.get("route", ""),
            "routeFixes": expand_route(fp.get("route", ""), dep, arr),
            "lat": lat, "lon": lon, "gs": gs, "hdg": p.get("heading", 0),
            "category": cat})
    flights.sort(key=lambda f: (f["category"], f["callsign"]))

    facs = nearby_facilities(feed, airspace, entry, boundaries, apts, firs)
    return {"ok": True, "airspace": airspace, "counts": counts, "total": len(flights),
            "flights": flights, "facilities": facs}


# ---------------- HTTP ----------------
class Handler(BaseHTTPRequestHandler):
    def log_message(self, fmt, *a):
        sys.stderr.write("  " + (fmt % a) + "\n")

    def _json(self, obj, code=200):
        body = json.dumps(obj).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        if self.path in ("/", "/index.html"):
            body = INDEX_HTML.encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        else:
            self.send_error(404, "Not found")

    def do_POST(self):
        try:
            length = int(self.headers.get("Content-Length", 0))
            payload = json.loads(self.rfile.read(length) or b"{}")
        except Exception as e:
            self._json({"ok": False, "error": "bad request: %s" % e}, 400); return

        # ---- Hub mode: forward to the central hub instead of Hoppie/VATSIM ----
        hub_url = (payload.get("hubUrl") or "").strip()
        cid = str(payload.get("cid") or "").strip()
        tok = (payload.get("hubToken") or "").strip()
        sid = str(payload.get("sid") or "").strip()
        vtok = (payload.get("verifyToken") or "").strip()
        if hub_url and cid:
            base = {"cid": cid, "token": tok, "sid": sid, "verifyToken": vtok}
            try:
                if self.path == "/api/vatsim":
                    out = hub_post(hub_url, "/hub/vatsim", base)
                elif self.path == "/api/poll":
                    out = hub_post(hub_url, "/hub/poll", base)
                elif self.path == "/api/send":
                    out = hub_post(hub_url, "/hub/send", dict(base,
                        to=(payload.get("to") or "").strip(), packet=payload.get("packet") or ""))
                elif self.path == "/api/altimeter":
                    out = hub_post(hub_url, "/hub/altimeter", dict(base,
                        icao=(payload.get("icao") or "").strip().upper()))
                else:
                    self._json({"ok": False, "error": "unknown endpoint"}, 404); return
                self._json(out)
            except Exception as e:
                self._json({"ok": False, "error": "hub unreachable: %s" % e}, 502)
            return

        if self.path == "/api/vatsim":
            station = (payload.get("airspace") or payload.get("from") or "").strip()
            if not station:
                self._json({"ok": False, "error": "airspace required"}, 400); return
            try:
                with _lock:
                    out = classify_traffic(station)
                self._json(out)
            except Exception as e:
                self._json({"ok": False, "error": "vatsim fetch failed: %s" % e}, 502)
            return

        if self.path == "/api/altimeter":
            icao = (payload.get("icao") or "").strip()
            alt, err = fetch_altimeter(icao)
            if err:
                self._json({"ok": False, "error": err}, 404 if "no metar" in err else 400)
            else:
                self._json({"ok": True, "icao": normalize_icao(icao), "altimeter": alt})
            return

        logon = (payload.get("logon") or "").strip()
        station = (payload.get("from") or "").strip()
        if not logon or not station:
            self._json({"ok": False, "error": "logon code and station id required"}, 400); return
        if self.path == "/api/send":
            fields = {"logon": logon, "from": station, "to": (payload.get("to") or "").strip(),
                      "type": (payload.get("type") or "cpdlc").strip(),
                      "packet": payload.get("packet") or ""}
        elif self.path == "/api/poll":
            fields = {"logon": logon, "from": station, "to": "SERVER", "type": "poll", "packet": ""}
        else:
            self._json({"ok": False, "error": "unknown endpoint"}, 404); return
        try:
            raw = hoppie_request(fields)
        except Exception as e:
            self._json({"ok": False, "error": "hoppie unreachable: %s" % e}, 502); return
        self._json(parse_hoppie(raw))


def _free_port(start):
    for p in range(start, start + 50):
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            if s.connect_ex(("127.0.0.1", p)) != 0:
                return p
    return start

def main():
    port = _free_port(PORT)
    url = "http://localhost:%d/" % port
    srv = ThreadingHTTPServer(("127.0.0.1", port), Handler)
    print("=" * 60)
    print("  vUSAlink is running.")
    print("  In your browser, open:  " + url)
    print("  (it should open automatically in a moment)")
    print("  Keep this window open while you work. Close it to quit vUSAlink.")
    print("=" * 60)
    threading.Timer(1.0, lambda: _open(url)).start()
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        print("\nshutting down."); srv.shutdown()

def _open(url):
    try:
        webbrowser.open(url)
    except Exception:
        pass


if __name__ == "__main__":
    main()
